import{_ as e,c as s,o as i,ax as l}from"./chunks/framework.cChzUWoi.js";const p=JSON.parse('{"title":"SQL 约束","description":"","frontmatter":{"title":"SQL 约束","date":"2019-08-20 20:21:48","tags":["database","odoo"],"categories":["database"]},"headers":[],"relativePath":"posts/database/SQL-constraints.md","filePath":"posts/database/SQL-constraints.md","lastUpdated":1767116845000}'),t={name:"posts/database/SQL-constraints.md"};function o(n,a,r,h,d,c){return i(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="sql-约束" tabindex="-1">SQL 约束 <a class="header-anchor" href="#sql-约束" aria-label="Permalink to “SQL 约束”">​</a></h1><h2 id="sql-语句-约束" tabindex="-1">SQL 语句 约束 <a class="header-anchor" href="#sql-语句-约束" aria-label="Permalink to “SQL 语句 约束”">​</a></h2><blockquote><p>约束用于限制加入表的数据的类型。</p></blockquote><h2 id="sql-unique-约束" tabindex="-1">SQL UNIQUE 约束 <a class="header-anchor" href="#sql-unique-约束" aria-label="Permalink to “SQL UNIQUE 约束”">​</a></h2><blockquote><p><code>UNIQUE</code> 约束唯一标识数据库表中的每条记录</p></blockquote><h2 id="sql-check-约束" tabindex="-1">SQL CHECK 约束 <a class="header-anchor" href="#sql-check-约束" aria-label="Permalink to “SQL CHECK 约束”">​</a></h2><blockquote><p><code>CHECK</code> 约束用于限制列中的值的范围<br> 如果对单个列定义 CHECK 约束，那么该列只允许特定的值<br> 如果对一个表定义 CHECK 约束，那么此约束会在特定列中对值进行限制。</p></blockquote><h2 id="sql-not-null-约束" tabindex="-1">SQL NOT NULL 约束 <a class="header-anchor" href="#sql-not-null-约束" aria-label="Permalink to “SQL NOT NULL 约束”">​</a></h2><blockquote><p><code>NOT NULL</code> 约束强制列不接受 <code>NULL</code> 值<br><code>NOT NULL</code> 约束强制字段始终包含值</p></blockquote><h2 id="sql-primary-key-约束" tabindex="-1">SQL PRIMARY KEY 约束 <a class="header-anchor" href="#sql-primary-key-约束" aria-label="Permalink to “SQL PRIMARY KEY 约束”">​</a></h2><blockquote><p>PRIMARY KEY 约束唯一标识数据库表中的每条记录<br> 主键必须包含唯一的值。主键列不能包含 NULL 值</p></blockquote><h2 id="sql-foreign-key-约束" tabindex="-1">SQL FOREIGN KEY 约束 <a class="header-anchor" href="#sql-foreign-key-约束" aria-label="Permalink to “SQL FOREIGN KEY 约束”">​</a></h2><blockquote><p>一个表中的 FOREIGN KEY 指向另一个表中的 PRIMARY KEY</p></blockquote><h2 id="sql-default-约束" tabindex="-1">SQL DEFAULT 约束 <a class="header-anchor" href="#sql-default-约束" aria-label="Permalink to “SQL DEFAULT 约束”">​</a></h2><blockquote><p><code>DEFAULT</code> 约束用于向列中插入默认值<br> 如果没有规定其他的值，那么会将默认值添加到所有的新记录</p></blockquote><h2 id="odoo-python-中的-sql-约束" tabindex="-1">odoo python 中的 sql 约束 <a class="header-anchor" href="#odoo-python-中的-sql-约束" aria-label="Permalink to “odoo python 中的 sql 约束”">​</a></h2><ul><li>内部的基本元素是一个(name, sql_definition, message)的元祖 <ul><li><code>@name</code>: 该约束的名称</li><li><code>@sql_definition</code>: 定义在数据库中的函数</li><li><code>@message</code>: 如果违反在数据库中的约束，将会显示的消息</li></ul></li></ul><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_sql_constraints </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;uniq_name&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;unique(name)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;name must be unique !&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span></code></pre></div>',18)])])}const b=e(t,[["render",o]]);export{p as __pageData,b as default};
